import { jest } from '@jest/globals';
import { BrowserWindow } from 'electron';
import { exportedForTests } from '_main/main';

jest.mock('electron', () => ({
  app: {
    on: jest.fn(),
    whenReady: jest.fn(() => Promise.resolve()),
  },
  ipcMain: { on: jest.fn() },
  BrowserWindow: jest.fn().mockImplementation(() => ({
    loadFile: jest.fn(() => Promise.resolve()),
    on: jest.fn(),
  })),
}));

test('Private props exported for unit tests', () => {
  expect(exportedForTests).toBeDefined();
});

test('func createWindow()', () => {
  const { createWindow } = exportedForTests!;

  createWindow();
  expect(BrowserWindow).toHaveBeenCalledTimes(1);
});

//  e2e test config for the monorepo root
const base = require('./jest.config.base');
const name = require('../../package.json').name;

module.exports = {
  ...base,
  displayName: `${name} e2e`,
  testPathIgnorePatterns: ['/node_modules/', '/packages/', '/test/unit/'],
};

// IMPORTANT: electron(v8) requires that the spectron(v10) is used
// the version of webdriverio bounds in spectron(v10) is `4.x`
// so the client api documentation is: http://v4.webdriver.io/api.html
import path from 'path';
import { Application } from 'spectron';

const electronPath: string = require('electron').toString();
const entryPath: string = path.join(__dirname, '../../packages/app-main/dist/main.prod.js');

let app: Application;

describe('application launch', () => {
  beforeAll(async () => {
    app = new Application({
      path: electronPath,
      args: [entryPath],
    });
    await app.start();
    await app.client.waitUntilWindowLoaded();
  }, 15000);

  afterAll(async () => {
    if (app && app.isRunning()) {
      await app.stop();
    }
  });

  it('should display window', async () => {
    const winCount = await app.client.getWindowCount();
    await app.client.windowByIndex(0);
    expect(winCount).toBe(1);
  });

  it('should display correct page content', async () => {
    const header = await app.client.getText(`[data-tid="home"]`);
    expect(header).toEqual('Home');
  });
});

import { defineConfig } from '@playwright/test';

export default defineConfig({
  testDir: '.',
  fullyParallel: false,
  workers: 1,
  timeout: 120000,
  expect: {
    timeout: 15000,
  },
  use: {
    trace: 'on-first-retry',
  },
});

